mapper.insert:
INSERT INTO REQUESTS ( KIND, KIND_DETAIL, CHARA, PRICE, CLIENT_NAME, RECEIVED_DAY, START_DAY, DEADLINE, PROGRESS, COMPLETED_DAY, TIP, TOTAL_WORK_TIME, STATUS, MEMO )
VALUES ( #{orderKind}, #{orderKindDetail}, #{chara}, #{price}, #{clientName}, #{receivedDay}, #{startDay}, #{deadLine}, #{progress}, #{completedDay}, #{tip}, #{totalWorkTime}, #{status}, #{memo}
)

mapper.select:
SELECT COUNT(*) >  0
FROM REQUESTS
WHERE CLIENT_NAME = #{clientName}
  AND KIND = #{orderKind}
  AND RECEIVED_DAY = #{receivedDay}
  AND PRICE = #{price}

mapper.update:
UPDATE REQUESTS
SET STATUS = #{status}
WHERE ID = #{requestId}

UPDATE REQUESTS
SET PROGRESS = COALESCE(PROGRESS,0) + #{progressGain}
WHERE ID = #{requestId}
